\label{thm:MainIntro}
	Fix $d\geq 2$, $\gamma>0$ and $0\leq\lambda\leq 1$. Consider the visibility region $Z_{\gamma,\lambda,d}$ of $o$ in a Poisson process of $\lambda$-geodesic hyperplanes in $\mathbb{H}^d$ with intensity measure $\gamma\nu_\lambda^o$.
	\begin{itemize}
	\item[(a)] Let $\gamma_{\mathrm{crit}}$ be as in \eqref{eq:GammaCrit}. If $\gamma<\gamma_{\mathrm{crit}}$, then $Z_{\gamma,\lambda,d}$ is unbounded with strictly positive probability, whereas if $\gamma>\gamma_{\mathrm{crit}}$, then $Z_{\gamma,\lambda,d}$ is almost surely bounded. Moreover, if $d=2$, then $Z_{\gamma_{\mathrm{crit}},\lambda,2}$ is almost surely bounded.

	\item[(b)] If $\gamma>\gamma_{\mathrm{crit}}$ then
	\begin{equation}\label{eq:MeanVolume}
		\mathbb{E}{\rm vol}_d(Z_{\gamma,\lambda,d})=\mathbb{E}{\rm vol}_d(Z_{\gamma,0,d}) = \pi^{\frac{d-1}{2}} \Gamma\left(\frac{d+1}{2}\right){\Gamma\big({\gamma_d^\ast-d+1\over 2}\big)\over\Gamma\big({\gamma_d^\ast+d+1\over 2}\big)}
	\end{equation}
	with $\gamma_d^\ast := \gamma\,{\Gamma({d\over 2})\over 2\sqrt{\pi}\Gamma({d+1\over 2})}$. On the other hand, $\mathbb{E}{\rm vol}_d(Z_{\gamma,\lambda,d})=+\infty$ for all $\gamma\leq\gamma_{\mathrm{crit}}$.
	\end{itemize}

