ref_dict.definition N and X:
\begin{definition}\label{definition N and X}
Given a spin initial data set $(M^n,g,k^1,\dots,k^m)$ and a spinor
$\psi\in\overline{\mathcal S}(M^n)$, we define the associated scalar field
\begin{align*}
N(\psi)&=|\psi|^2.
\end{align*}
We also define the associated vector fields $X^{\alpha}(\psi)$ on $M$ by
\begin{align*}
\langle X^{\alpha}(\psi), Y\rangle &=\langle Y \eta_\alpha\psi,\psi\rangle,
\end{align*}
where $Y$ is an arbitrary vector field on $M$.  In particular, for a coordinate vector $e_i$, 
\begin{align*}
    X^{\alpha}_i(\psi) = \langle e_i \eta_{\alpha} \psi, \psi\rangle.
\end{align*}
For brevity, we denote $N(\psi)$ and $X^\alpha(\psi)$ by $N$ and $X^\alpha$.
We further introduce the modified spin connection and Dirac operator
\begin{align*}
\overline{\nabla}_i\psi
&=\nabla_i\psi+\frac12\sum_{\alpha=1}^m k^\alpha_{ij}e_j\eta_\alpha\psi,\\
\overline{\slashed D}\psi
&=e_i\overline{\nabla}_i\psi.
\end{align*}
\end{definition}

ref_dict.N=X:
\begin{theorem} \label{N=X}
In the setting of Theorem \ref{l.i spinor} with $\psi$ satisfying~\eqref{equation spacetime harmonic spinor}, $N=|X^\alpha|$ for any $\alpha=1,...,m$, i.e.\ $\psi$ is everywhere null. Moreover, $X^\alpha$ is perpendicular to $X^\beta$, for any $\alpha\neq \beta$.
\end{theorem}

ref_dict.main technical:
\begin{theorem}\label{main technical}
Let $\psi$ be as in \eqref{psi overdetermined intro}, and let $\mathcal{M} = \{1, \dots, m\}$.
Then either $\psi$ is everywhere null or $\psi$ is everywhere timelike.
In the latter case, the spinor
\begin{align*}
    \varphi=\eta_\mathcal{M} \sum_{|I|=|\Gamma|} (-1)^{|\Gamma|}\langle e_I \eta_\Gamma\psi,\psi\rangle e_I \eta_\Gamma\psi
\end{align*}
also solves 
\begin{align*}
    \nabla_i\varphi+\frac12\sum_{\alpha=1}^mk^\alpha_{ij}e_j\eta_\alpha\varphi=0.
\end{align*}
\end{theorem}

