\begin{equation}\label{eq:sum:eul:char:XD}
	\sum_{r \, | \, f}\chi(X_{r^2D_0}) =\frac{1}{30}\cdot\sum_{\substack{e \equiv D \, [2]}} \sigma_1\left(\frac{D-e^2}{4}\right)
	\end{equation}
\end{Corollary} 

\subsection{Product locus in $X_D$}\label{subsec:prod:locus}
Following \cite{Bai:GT}, we call the locus of points in $X_D$ which represent Abelian surfaces that are (polarized) product of elliptic curves the {\em product locus} of $X_D$ and denote it by $P_D$. Generic points in $X_D$ represents  Jacobians of smooth genus two curves. A point in $P_D$ represents the Jacobian of a singular curve having two irreducible components of genus one intersecting at a separating node. 
It is well known that $P_D$ is a union of modular curves \cite{Hir73, vdG88}. 
In \cite{Bai:GT}, Bainbridge proved the following
\begin{Theorem}[Bainbridge]\label{th:Bain:eul:char:PD}
	If the discriminant $D$ is not a square then we have 
	\begin{equation}\label{eq:eul:char:PD}
		\chi(P_D) = -\frac{5}{2}\cdot \chi(X_D).
	\end{equation}

ref_dict.prop:eul:char:XD:p:
\begin{Proposition}[M\"oller]\label{prop:eul:char:XD:p}
	Assume that $D\equiv 0,1,4 \; [8]$ and $D=f^2D_0$, where $D_0> 1$ is a fundamental discriminant. Then we have
	\begin{equation}\label{eq:eul:char:XD:p:ratio}
	\frac{\chi(X'_D)}{\chi(X_D)} =\left\{ 
	\begin{array}{ll}
		1 & \hbox{ if $2 \nmid f$},\\
		3/2 & \hbox{ if $2 \, | \, f$}.
	\end{array}
	\right.
     \end{equation} 
\end{Proposition}

ref_dict.th:SV:const:
\begin{Theorem}\label{th:SV:const}
	For all $D\in \N, \; D >9, D \equiv 0,1,4 \, [8]$, and $D$ is not a square, we have
	$$
	c_1(D) = \frac{25}{9}, \quad c_2(D)= 3, \quad c_3(D) = \frac{2}{9}.
	$$
\end{Theorem}

post_theorem_intro_text:
The loci $\Omega E_D(2,2)^\mathrm{odd}$ are all contained in the locus  $\tilde{\mathcal{Q}}(4,-1^4)$ of orienting double covers of quadratic differentials in the stratum $\mathcal{Q}(4, -1^4)$.
Since the loci $\Omega E_D(2,2)^\mathrm{odd}$ are not contained in any proper invariant sub-orbifold of $\tilde{\mathcal{Q}}(4,-1^4)$ (see \cite{AN16})
it follows from the results of Eskin-Mirzakhani~\cite{EM18} and Eskin-Mirzakhani-Mohammadi~\cite{EMM13} that  as $D\to +\infty$, $c_k(D)$ converges to the corresponding Siegel-Veech constant of $\tilde{\mathcal{Q}}(4,-1^4)$ that we denote by $\tilde{c}_k(4,-1^4)$. In Appendix~\ref{sec:SV:quad:cov}, we will give the proof that $\tilde{c}_1(4,-1^4)=25/9, \;, \tilde{c}_2(4,-1^4)= 3, \; \tilde{c}_3(4,-1^4)=2/9$ using the method of Eskin-Masur-Zorich~\cite{EMZ03}. 

\medskip

Hilbert modular surfaces are moduli spaces of Abelian surfaces admitting a real multiplication by some quadratic order  (see \textsection~\ref{sec:Hilbert:mod:surf} for more details). Let $X_D$ be the Hilbert  surface parametrizing principally polarized Abelian surfaces admitting a  multiplication by $\Oc_D$.  In this paper, we will be interested in Abelian surfaces with polarization of type $(1,2)$. The corresponding Hilbert surface  will be denoted by $X'_D$. Note that $X'_D=\varnothing$ if $D\equiv 5 \; [8]$ (see \cite{LN:components, Mo14}).

Let $P_D$ (resp. $P'_D$) denote the product locus of  $X_D$ (resp. of $X'_D$) that is the locus of Abelian surfaces $A \simeq E_1\times E_2$, where $E_1, E_2$ are elliptic curves (see \textsection\ref{subsec:prod:locus} for more details). 
The loci $P_D$ and $P'_D$ are finite covers of the modular curve $\mathbb{H}/{\rm SL}(2,\Z)$. 
In \cite{Bai:GT}, Bainbridge showed that for all non-square discriminant $D >4$, we have
$$
\chi(P_D)=-\frac{5}{2}\cdot\chi(X_D)
$$
where $\chi(.)$ denotes the Euler characteristic. As a by product of the proof of Theorem \ref{th:SV:const}, we will show
\begin{Theorem}\label{th:eul:char:PD:p:XD:p}
	For all $D\in \mathbb{N}, D\equiv 0,1,4 \, [8]$, $D>9$ and $D$ is not a square, we have
	\begin{equation}\label{eq:eul:char:PD:p:XD:p}
		\chi(P'_D) =\left\{ 
		\begin{array}{ll}
			-\chi(X'_D) & \hbox{ if $D\equiv 1 \, [8]$} \\
			-\chi(X'_D)/2 & \hbox{ if $4 \, | \, D$}.
		\end{array} 
		\right.
	\end{equation}

\end{Theorem} 
\subsection{Ideas of the proof}\label{subsec:strategy}
Let $\Omega E_D(2)$ and $\Omega E_D(4)$ denote the Prym eigenfom loci with discriminant $D$ in the strata $\Omega \Mcal_2(2)$ and $\Omega \Mcal_3(4)$ respectively. Each of these loci is a finite union of closed ${\rm GL}^+(2,\mathbb{R})$-orbits  (see \cite{McM:prym}). Let $W_D(2)$ (resp. $W_D(4)$) denote the projectivization of $\Omega E_D(2)$ (resp. of $\Omega E_D(4)$), that is $W_D(2)\simeq \Omega E_D(2)/\mathbb{C}^*$ (resp. $W_D(4)\simeq \Omega E_D(4)/\mathbb{C}^*$). Note that $W_D(2)$ (resp. $W_D(4)$) is isomorphic to a finite union of Teichm\"uller curves.    

To our purpose, we will consider Abelian differentials on disconnected Riemann surfaces. In \cite{Ng:25} (see also \cite{LN:components}), we introduced the notion of Prym eigenforms on triples of tori. The space of triples of tori that are Prym eigenforms for the quadratic order $\Oc_D$ is denoted by $\Omega E_D(0^3)$, and its projectivization  $\Omega E_D(0^3)/\mathbb{C}^*$  by $W_D(0^3)$. It can be shown that $W_D(0^3)$ is a (non-connected) finite cover of the modular curve $\mathbb{H}/{\rm SL}(2,\Z)$. The following result was proved in \cite{Ng:25}.
\begin{Theorem}\label{th:Siegel:Veech}
	Let $D \equiv 0, 1, 4 \;  [8], \, D >9$, be a non-square discriminant. 	
	\begin{itemize} 
		\item[$\bullet$] If $4 \, | \, D$,  then we have
		\begin{align*}
			c_1(D) & = \frac{15\chi(W_D(4))}{\chi(W_D(2))+b_D \chi(W_{D/4}(2))+9\chi(W_D(0^3))}\\
			c_2(D) &= \frac{9\left(\chi(W_{D}(2)) + b_D\chi(W_{D/4}(2)) \right)}{\chi(W_D(2))+b_D \chi(W_{D/4}(2))+9\chi(W_D(0^3))} \\
			c_3(D) & = \frac{3\chi(W_D(0^3))}{\chi(W_D(2))+b_D \chi(W_{D/4}(2))+9\chi(W_D(0^3))}
		\end{align*}
		with
		$$
		b_D= \left\{
		\begin{array}{ll}
			0 & \text{ if } D/4 \equiv 2,3 \, [4] \\
			4 & \text{ if } D/4 \equiv 0 \, [4] \\
			3 & \text{ if } D/4 \equiv 1 \, [8] \\
			5 & \text{ if } D/4 \equiv 5 \, [8]. \\
		\end{array}
		\right.
		$$
		\item[$\bullet$] If $D\equiv 1 \; [8]$, then
		\begin{align*}
		c_1(D) & = \frac{15\chi(W_{D}(4))}{2\chi(W_D(2))+9\chi(W_D(0^3))}\\
		c_2(D) &= \frac{18\chi(W_{D}(2))}{2\chi(W_{D}(2))+9\chi(W_D(0^3))} \\
		c_3(D) & = \frac{3\chi(W_{D}(0^3))}{2\chi(W_{D}(2))+9\chi(W_D(0^3))}.
		\end{align*}
	\end{itemize}	
\end{Theorem}
 For any $D \in \mathbb{N}$, $D >9$ non-square and $D\equiv 0,1,4 \, [8]$, by a result of M\"oller~\cite{Mo14}, we have that
 $$
 \chi(W_D(4))=\left\{
 \begin{array}{cl}
 {\displaystyle -\frac{5}{2} \cdot\chi(X'_D)} & \hbox{ if $D \equiv 0 \, [4]$} \\
 {\displaystyle -5\cdot\chi(X'_D)} & \hbox{ if $D \equiv 1 \, [8]$}.	 
 \end{array}
 \right.
 $$
 It was shown by Bainbridge in \cite{Bai:GT} that we have 
 $$
 \chi(W_D(2))=-\frac{9}{2}\cdot\chi(X_D).
 $$
 In the same paper, Bainbridge also gave an explicit formula computing $\chi(X_D)$ generalizing a classical result of Siegel.  In \cite{Mo14}, M\"oller proved an explicit formula relating  $\chi(X'_D)$ to $\chi(X_D)$ (cf. Proposition~\ref{prop:eul:char:XD:p}). Combining these results,  we will show that 
 $$
 \chi(W_D(2)) +b_D\chi(W_{D/4}(2))= -\frac{9}{2}\chi(X'_D).
 $$  
To prove Theorem~\ref{th:SV:const}, it remains to show that we have
$$
\chi(W_D(0^3))= \left\{ 
\begin{array}{rl}
	-\chi(X'_D) & \hbox{ if $D\equiv 0 \, [4]$} \\
	-2\chi(X'_D) & \hbox{ if $D \equiv 1 \, [8]$}
\end{array} 
\right.
$$
This is achieved by relating $\chi(W_D(0^3))$ to  coefficients of the Fourier expansion of some modular forms. 

