\begin{theorem}\label{main_thm} If $0<p<3/4$ then there exists positive constants $C_1$, $C_2$, $C_3$ and $C_4$ such that, for all $N \ge 2$ and $t \geq 1$, the following bound holds:

    \begin{equation*}
        C_1 \exp \left( -C_2 \frac{t}{N^2} \right) \leq \P \left( \tau_N > t \right) \le C_3 \exp \left(-C_4\frac{t}{N^2}\right).
    \end{equation*}
\end{theorem}

