\begin{corollary}\label{cor}
Under the hypotheses of Theorem \ref{thm 1}, we have 
\begin{align*}
\sigma_1(\Omega; \gamma_h)\le \sigma_1(B; \gamma_h).
\end{align*}
Equality holds if and only if $\Omega$ is isometric to the round ball $B$.
\end{corollary}

