The paper says that, in establishing the main theorem, it combines (i) curvature estimates away from finitely many points (derived after describing the geometry of ends of complete immersed minimal submanifolds with finite total curvature, leading to the following lemma. \begin{lemm}\label{lemm:curv.est}
For fixed $I \in \ZZ^+,0 <r_0<R_0< \infty\,,$ suppose that $M_j( \iota_j :M_{j} \to  \RR^{n+m})$ is a sequence of $n$-dimensional complete properly immersed minimal submanifolds with nonempty boundary and $\iota_j(M_j) \subset B_{R_0}(0)$ such that $ \int_{M_j} \abs{A_{M_j}}^n d\mu_{M_j} < IK_0 , \limsup \limits_{j\to \infty}\nu_j(B_{R_0}(0)\setminus B_{\fh{r_0}{2}}(0))< K_0$ and $\vol(B_R(q)) \leq \Lambda R^n$ for any $B_R(q) \subset B_{R_0}(0)$. Then, after passing to a subsequence, we have:
\begin{enumerate}[itemsep=5pt, topsep=5pt]
    \item There exist $C>0$ and a sequence of smooth blow-up sets $\cB_{j} \subset M_{j}$  so that 
\begin{equation} \label{eq:seq.cur.esti}
    |A_{M_{j}}|(x)d(\iota_j(x),\iota_j(\cB_{j} \cup \de M_j) ) \leq C\, , \ |\cB_{j}|< I\, , \ \iota_j(\cB_j) \subset B_{\fh{3}{4}r_0}(0)\, ,
\end{equation}
for all $x \in M_{j}\,.$ 
\item  $\iota_j(\cB_j)$ converges to $ \widetilde  \cB_ \infty \subset \RR^{n+m}$ in the Hausdorff distance sense and  the Radon measure $\nu_j$ converges to $ \nu_\infty$ in the Radon measure sense with $\nu_\infty(p_\infty)\geq 2K_0$ for any $p_\infty \in \widetilde \cB_\infty\,.$
\end{enumerate}
\end{lemm}) with (ii) a key topological result controlling the topology of the “intermediate regions” (the following lemma. \begin{lemm}[Annular decomposition] \label{lemm.Annular.composition}
For fixed $n\,,m\in \ZZ^+\,,n\geq 2\,,$ there is a $0 < \sigma_0 <\fh{1}{2} $ only depending on $n,m$ with the following property. Suppose that $M^n(\iota : M^n \to \bar{B_2(0)} \subset\RR^{n+m})$ is a complete properly immersed submanifold  with $\iota(\de M)  \subset \de B_2(0)\, . $ Assume that for some $\sigma \leq \sigma_0$ and $p \in B_{\sigma_0}(0)\,,$ we have:
\begin{enumerate}[itemsep=5pt, topsep=5pt]
\item For each component $M'$ of $M\,,$ $M' \cap B_{\sigma}(p) \neq \emptyset \,$.
\item The immersed submanifold $M$ intersects $\de B_{\sigma}(p)$ transversely, and $M \cap \de B_{\sigma}(p)$ has $k$ components. Moreover, each component of   $M \cap \de B_{\sigma}(p)$ is diffeomorphic to $\SS^{n-1}$ with the standard smooth structure.
\item The second fundamental form of $M$ satisfies $|A|(x)|\iota(x)-p| \leq \fh{1}{4} $ for all $x \in M \cap \left( \overline{B_{1}(0)} \setminus B_{\sigma}(p) \right)\,.$
\end{enumerate}
Then, $M$ intersects $\de B_{1}(0)$ transversely. Both  $M \cap \left(\overline{B_{1}(0)}\setminus {B_{\sigma}(p)}\right)$ and  $M \cap \de B_{1}(0)$  have $k$ components. Moreover, each component of   $M \cap \de B_{1}(0)$ is diffeomorphic to $\SS^{n-1}$ with the standard smooth structure and
 each component of $M \cap \left(\overline{B_{1}(0)}\setminus {B_{\sigma}(p)}\right)$ is diffeomorphic to $\SS^{n-1}\times [0,1]$ with the standard smooth structure.
\end{lemm}); together these complete the proof of the main theorem “by an induction argument on the total curvature.” It also notes a difficulty compared to \cite{Chodosh17}: a concentration point “may be a non-flat minimal submanifold with finite total curvature” rather than a plane, which is resolved (in the following theorem) via the same kind of induction-on-total-curvature argument. \begin{theo} \label{prop.diffeo}
Given a sequence $M_{j}$ satisfying \hyperlink{defi:beth}{$(\beth)$} and each $M_j$  intersects $\partial B_{1}(0)$ transversely. By passing to a subsequence, all of the $M_{j}\cap B_{1}(0)$ are diffeomorphic. 
\end{theo}

expanded_theorem:
\label{theo.finite.top}
For fixed $n\,,m \in \mathbb{Z}^+\,,n \geqslant 3\,, m \geq1\,,$ and $ \Gamma \, ,\Lambda \in \mathbb{R} \, ,  \Gamma\,,\Lambda \geqslant 0\,$, there exists $N = N(n,m,\Gamma,\Lambda) \in \mathbb{N}$ so that there are at most $N$ mutually non-diffeomorphic complete immersed minimal submanifolds $M^n$ in $\mathbb{R}^{n+m}$ satisfying that  $\int_{M} \lvertA\rvert^{n}d\mu_M  \leqslant \Gamma$ and 
$\vol_M ( B_R(0)) \leqslant  \Lambda R^n$ for any $R>0\,.$

theorem.content:
\label{main1} Let $(M,g)$ be a closed Riemannian $n$-manifold with ${\rm Ric} \geq (n-1)\xi$, ${\rm inj}(M)\geq r_0$, ${\rm diam}(M) \leq D<\infty$. Then there exist positive constants $c(n,D,\xi,r_0,p)$ and $c'(n,D,\xi,r_0,p)$  such that
\begin{equation} \label{eq:vol_lower_bound}
    \lambda_{1,p}(M) \ge \frac{c(n,p,\xi,r_0)}{{V_\xi(D)} . e^{{c'(n,D,\xi,r_0,p)V_\xi(D)}}},
\end{equation}
    where $V_{\xi}(D)$ denotes the volume of a ball of radius $D$ in a space of constant curvature $\xi.$

ref_dict.maincor:
\begin{corollary} \label{maincor}
 Let $(M,g)$ be a closed $n$-manifold with non-negative curvature operator. If the injectivity radius of $(M,g)$ is greater than $r_0$ and the diameter is bounded by $ D$ then there exist positive constants $c(n,p,r_0)$ and $C(n,D,r_0)$ such that the first non-zero eigenvalue $\lambda^C_{1,p}$ of the connection Laplacian $\nabla^{*} \nabla$ acting on the space of $p$-forms satisfies
    \[  \frac{c(n,p,r_0)}{{D^n} . e^{{c'(n,p,r_0)D^n}}}\le \lambda_{1,p}^C\le C(n,D,r_0), \quad {\rm for} \ \ 1 \le p\le n.\]
    \end{corollary}

ref_dict.main1:
\begin{theorem}\label{main1} Let $(M,g)$ be a closed Riemannian $n$-manifold with ${\rm Ric} \geq (n-1)\xi$, ${\rm inj}(M)\geq r_0$, ${\rm diam}(M) \leq D<\infty$. Then there exist positive constants $c(n,D,\xi,r_0,p)$ and $c'(n,D,\xi,r_0,p)$  such that
\begin{equation} \label{eq:vol_lower_bound}
    \lambda_{1,p}(M) \ge \frac{c(n,p,\xi,r_0)}{{V_\xi(D)} . e^{{c'(n,D,\xi,r_0,p)V_\xi(D)}}},
\end{equation}
    where $V_{\xi}(D)$ denotes the volume of a ball of radius $D$ in a space of constant curvature $\xi.$ 
\end{theorem}

ref_dict.thm:volume:
\begin{theorem}
\label{thm:volume}
 Let $(M,g)$ be a closed Riemannian $n$-manifold with volume $V$. Assume that the Ricci curvature satisfies $\mathrm{Ric}_g \ge (n-1)\xi .$ Then   

\[
\lambda_{k,p}
\le
C(n,p)|\xi|^{n/2}(1+r_H^2)\left[\frac{k+1}{\theta_kV}\right]^{\frac{n+1}{n}}.
\]
where $\theta_k=\min\{1,\frac{\omega_n k}{V|\xi|^{\frac{n}{2}}},\frac{\omega_n k}{V|\xi|^{\frac{n}{2}}}(sinh(4r_H\sqrt{|\xi|}))^n\}.$
\end{theorem}

ref_dict.thm:harmonic_radius:
\begin{theorem}{\cite{CheegerAnderson,Hebey}}
\label{thm:harmonic_radius}
Let $(M,g)\in \mathcal{M}(n,\xi,r_0)$. For $n<q<\infty$, there exists a positive constant $r_H=r_H(q, (n,\xi,r_0))<r_0$ such that on any ball of radius $r_H$  a harmonic coordinate chart $\{x_i\}_{i=1}^n$ is defined. If $g_{ij}=g\big{(}\frac{\partial}{\partial x_i},\frac{\partial}{\partial x_j}\big{)}$  then
\begin{enumerate}
    \item $\frac{1}{2}\delta_{ij}\leq g_{ij}\leq 2\delta_{ij}$, and
    \item $r_H^{1-n/q}\|\partial g_{ij}\|_{L^q}\leq 1$.
\end{enumerate}
\end{theorem}

ref_dict.lem:upper_bound_dirichlet_eigenvalue:
\begin{proposition}    \label{lem:upper_bound_dirichlet_eigenvalue}
Let $0<\varepsilon\le r_H$, $(M,g)\in \mathcal{M}(n,\xi,r_0)$ and $x\in M.$ For $B=B(x, \varepsilon)$, there exists a positive constant $C(n,p)$ such that,  
\[\lambda_{0,p}^{D}(B)\leq C(n,p)(1+ r_H^2)\frac{V_\xi(\varepsilon)}{\varepsilon^2 V_\xi(\frac{\varepsilon}{2})}.\]
\end{proposition}

ref_dict.einstein:
\begin{corollary} 
\label{einstein}
Let $(M,g)$ be a closed $n$-manifold with ${\rm inj}(M,g) \ge r_0$, ${\rm diam}(M) \le D <\infty$, $ {\rm Ric}_g = -(n-1)\xi$. Let $\lambda_{k,1}^C$ be the $k$-th eigenvalue of the connection Laplacian $\nabla ^{*} \nabla $. Then there exist positive constants $c(n,D,\xi,r_0)$ and $C(n,D,\xi,r_0)$ depending only on $n,D,\xi,r_0$ such that
  \[c(n,D,\xi,r_0)\le \lambda_{k,1}^C\le C(n,D,\xi,r_0).\]
   \end{corollary}

ref_dict.cor:connectionLap:
\begin{corollary} \label{cor:connectionLap}
    Let $(M,g)$ be a closed $n$-manifold with ${\rm inj}(M,g) \ge r_0$, ${\rm diam}(M) \le D <\infty$, $ {\rm Ric}_g \ge 0$. Then the first non-zero eigenvalue $\lambda^C_{1,1}$ of the connection Laplacian $\nabla^{*} \nabla$ acting on the space of $1$-forms satisfies
    \[c(n,D,r_0)\le \lambda_{1,1}^C\le C(n,D,r_0).\]
\end{corollary}

ref_dict.thm:spectral_equivalence:
\begin{theorem}[Spectral equivalence]
\label{thm:spectral_equivalence}
Let $(M,g)\in \mathcal{M}(n,\xi,r_0)$, and let $X$ be an $\varepsilon$-discretization
with $0<4\varepsilon<r_H$. Then for all degrees $1\le p\le n-1$ and all
\[
1\le k \le |S_p(\mathcal{U}_X)| - \tilde b_p(\mathcal{U}_X),
\]
there exist constants $C_L,C_U>0$, depending only on $(n,p,\xi,r_0,\varepsilon)$,
such that
\begin{equation}\label{eq:spec_equiv}
    C_L\,\lambda_{k,p}(X)
    \;\le\;
    \lambda_{k,p}(M)
    \;\le\;
    C_U\,\lambda_{k,p}(X).
\end{equation}
\end{theorem}

ref_dict.lem:manifoldanddirichlet:
\begin{lemma}
\label{lem:manifoldanddirichlet}    
Let $(M,g)$ be a closed Riemannian $n$-manifold and $D_1,\dots,D_j \subset M$ be pairwise disjoint domains in M. Let $\lambda^{D}_{j,p}(D_i)$ be the eigenvalue of the Hodge Laplacian $\Delta_p$ acting on $p$-forms on $D_i$
with absolute Dirichlet boundary conditions. Then, 
\begin{equation}\label{eq:domain_upper}
\lambda_{jl - 1,p}(M,g)
\;\le\;
\max_{1 \le i \le j} \lambda^{D}_{l-1,p}(D_i) 
\end{equation}
\end{lemma}

ref_dict.thm:main_theorem:
\begin{theorem} \label{thm:main_theorem}
Let $(M,g)$ be a closed Riemannian $n$-manifold with diameter $D$ and harmonic radius greater than $r_H$. Assume that the Ricci curvature satisfies $\mathrm{Ric}_g \ge (n-1)\xi .$  Then there exists a positive constant $C(n,p)$ such that

\[\lambda_{k,p}\le C(n,p)(1+ r_H^2)\frac{V_\xi(\frac{D}{2k})}{ V_\xi(\frac{D}{4k})}\frac{k^2}{D^2},\qquad \forall k\ge\frac{D}{2r_H}\]
and \[\lambda_{k,p}\le C(n,p)(1+ r_H^{-2})\frac{V_\xi(r_H)}{ V_\xi(\frac{r_H}{2})},\qquad \forall k\le \frac{D}{2r_H}.\]
\end{theorem}

ref_dict.lem:PoincareLemma:
\begin{lemma}[Poincar\'e Lemma] \label{lem:PoincareLemma}
    Let $p>0$ and $\mathcal{U}$ be a contractible cover. Let $\omega \in \mathcal{C}^q(\mathcal{U},\Lambda^p)$ such that $d \omega = 0$. Then there exists $\eta \in \mathcal{C}^q(\mathcal{U},\Lambda^{p-1})$ such that $d \eta = \omega$.
\end{lemma}

ref_dict.lem:localspectralgap:
\begin{lemma} \label{lem:localspectralgap}
    Let $0< \varepsilon<\frac{r_H}{4}$, $(M,g) \in \mathcal{M}(n,\xi,r_0)$, and let $X$ an $\varepsilon$-discretization of $(M,g)$ with associated cover $\mathcal{U}_X = \{B(x_i,2 \varepsilon)\}$. For every $0\leq p\le n$ and every $I \in S_p(\mathcal{U}_X)$, the first nonzero eigenvalue of the 
Hodge Laplacian on $U_I$ with absolute boundary conditions satisfies
\begin{equation} \label{eq:localspectralgap}
    \lambda^{\mathrm{abs}}_{1,p}(U_I)
\;\ge\;
\frac{\kappa(n,p)}{\varepsilon^2},
\end{equation}
where $\kappa(n,p)>0$ depends only on $n$ and $p$ and is independent of the index set $I$.  
\end{lemma}

expanded_sketch:
\textbf{Idea of the proof (for the main theorem):} The approach “mostly rely[ies] on the existence of harmonic coordinate charts and a uniform harmonic radius,” since “the only curvature assumption imposed is a lower bound on the Ricci curvature.” One “discretize[s] the manifold by choosing a scale smaller than the uniform harmonic radius,” and from the resulting open cover “associate[s] the \v{C}ech cochain complex defined using the coboundary operator,” which “is then used to define a combinatorial Laplacian”; this construction (adapted from Mantuano) is described as “crucial to the proof.” A key modification is that “the crucial Lemma~2.10 of \cite{Tatiana} requires rework,” and “due to the existence of the uniform harmonic radius, $r_H$,” as provided by the following theorem.

\begin{theorem}{\cite{CheegerAnderson,Hebey}}
\label{thm:harmonic_radius}
Let $(M,g)\in \mathcal{M}(n,\xi,r_0)$. For $n<q<\infty$, there exists a positive constant $r_H=r_H(q, (n,\xi,r_0))<r_0$ such that on any ball of radius $r_H$  a harmonic coordinate chart $\{x_i\}_{i=1}^n$ is defined. If $g_{ij}=g\big{(}\frac{\partial}{\partial x_i},\frac{\partial}{\partial x_j}\big{)}$  then
\begin{enumerate}
    \item $\frac{1}{2}\delta_{ij}\leq g_{ij}\leq 2\delta_{ij}$, and
    \item $r_H^{1-n/q}\|\partial g_{ij}\|_{L^q}\leq 1$.
\end{enumerate}
\end{theorem}

Together with domain monotonicity results, this yields the required spectral gap. Next, “in Lemma~\ref{lem:localspectralgap}, we derive a spectral gap on the Hodge-Laplacian with absolute boundary conditions,” namely:

\begin{lemma} \label{lem:localspectralgap}
    Let $0< \varepsilon<\frac{r_H}{4}$, $(M,g) \in \mathcal{M}(n,\xi,r_0)$, and let $X$ an $\varepsilon$-discretization of $(M,g)$ with associated cover $\mathcal{U}_X = \{B(x_i,2 \varepsilon)\}$. For every $0\leq p\le n$ and every $I \in S_p(\mathcal{U}_X)$, the first nonzero eigenvalue of the 
Hodge Laplacian on $U_I$ with absolute boundary conditions satisfies
\begin{equation} \label{eq:localspectralgap}
    \lambda^{\mathrm{abs}}_{1,p}(U_I)
\;\ge\;
\frac{\kappa(n,p)}{\varepsilon^2},
\end{equation}
where $\kappa(n,p)>0$ depends only on $n$ and $p$ and is independent of the index set $I$.  
\end{lemma}

Then, “using this spectral gap and a version of the Poincar\'e Lemma,” i.e. the following statement,

\begin{lemma}[Poincar\'e Lemma] \label{lem:PoincareLemma}
    Let $p>0$ and $\mathcal{U}$ be a contractible cover. Let $\omega \in \mathcal{C}^q(\mathcal{U},\Lambda^p)$ such that $d \omega = 0$. Then there exists $\eta \in \mathcal{C}^q(\mathcal{U},\Lambda^{p-1})$ such that $d \eta = \omega$.
\end{lemma}

the construction of the discretization operator that associates smooth forms to \v{C}ech cochains follows. This “discretization operator is then used to obtain a lower bound for the first eigenvalue of the Hodge Laplacian on $p$-forms” in terms of “the dimension, lower bounds on the Ricci curvature and injectivity radius, and an upper bound on the diameter of the manifold,” emphasizing that the method extends Mantuano’s sectional-curvature setting to “only assume a lower bound on Ricci curvature.” This completes the proof strategy for the main theorem.

