\item[(II)] Suppose that there are two vertices $u_{i1}, u_{i2} \in N(u_i)$ with $d(u_{i1})=d(u_{i2})=2$ and $u_{i1}u_{i2}\in E(G)$ for some $i\in [2]$. Then $G+u_1u_2$ contains a copy of $tP_4$ as $u_1u_2\notin E(G)$. In this case $u,u_{i1}, u_{i2} \notin V(T(u_1u_2)-P_4(u_1u_2))$. However, $(T(u_1u_2)-P_4(u_1u_2)) \cup \{uu_iu_{i1}u_{i2}\}$ is a copy of $tP_4$ in $G$,  a contradiction. 

\item[(III)] Let $N(u_i)=\{u,u_{i1},\ldots,u_{i(d(u_i)-1)}\}$. Suppose $d(u_2)\ge 3$ and there are at most two vertices in $N(u_2)$ of degree greater than $1$, that is, $d(u_{2j})=1$ for any $u_{2j}\in N(u_2)\setminus\{u,u_{21}\}$. Since $uu_{21}\notin E(G)$, $G+uu_{21}$ contains a copy of $tP_4$. In this case $u_{1}, u_{2} \notin V(T(uu_{21})-P_4(uu_{21}))$. However, $(T(uu_{21})-P_4(uu_{21})) \cup \{u_1uu_{2}u_{21}\}$ is a copy of $tP_4$ in $G$, a contradiction. 

\item[(IV)] Suppose that $d(u_1)=2$. Since $u_2u_3\notin E(G)$ where $u_3\in N(u)$, we see that $G+u_2u_3$ contains a copy of $tP_4$ and $u, u_{1} \notin V(T(u_2u_3)-P_4(u_2u_3))$. It follows that $(T(u_2u_3)-P_4(u_2u_3)) \cup \{u_2u_1uu_3\}$ is a copy of $tP_4$ in $G$, which is a contradiction. 
    \end{itemize}

     Therefore, the proof is complete. 
 \end{proof}

\section{The Proof of Theorem \ref{tp4suffcondi}}\label{toolpf}
\begin{theproof}[Proof of Theorem \ref{tp4suffcondi}]
Let $\rho$ be the spectral radius of $G$. Suppose that $p(x)=x^3-2x^2-3x+4.$ By Lemma \ref{lemrho-p}, we have 
