\begin{proof}
 Let $B_1=\{w: w\in N_2(v)\text{ and }|N(w)\cap N(v)|=1\}$ and $B_2=\{w: w\in N_2(v)\text{ and }|N(w)\cap N(v)|\geq 2\}$. Then
    \begin{align*}
        \sum_{w\in N_2(v)}|N(w)\cap N(v)| \cdot d(w)&\geq \sum_{w\in B_1}d(w)+\sum_{w\in B_2}2d(w)\\
&\geq 2|B_1|+2e(A,B_2)\\
&= 2e(A,B_1)+2e(A,B_2)\\
&= 2e(A,B),
    \end{align*}
     and equality holds if and only if $d(w)=2$ for any $w\in N_2(v)$. 
\end{proof}

