    \item [\rm iv)] $d(v_1)=3$: By Lemma \ref{deg=1} and Lemma \ref{lemdeg-eq} (II) and $n\geq 8$, we have $e(B,C)\geq 2=e(A,B)$. Hence $F(v)\geq 0$.
\end{itemize}

