\begin{remark}[Rate of Convergence]\label{remark-sharpasymp}
According to the proof of Theorem~\ref{thm-2} and the proof of Lemma~\ref{lemma-convconc} in Appendix~\ref{app-convconc}, if $(\mu_t,\nu_t)$ converges to the mixed Nash equilibrium (MNE) $(\mu^*,\nu^*)$, then
\begin{equation}\label{eq-gapp}
W_2(\mu_t,\mu^*) + W_2(\nu_t,\nu^*) = O(e^{-\lambda t})
\quad \text{for all } \lambda \in (0,\lambda_{\mathrm{gap}}).
\end{equation}
Moreover, the constant $\lambda_{\mathrm{gap}}=\lambda_{gap}(f)>0$ (we call it spectral gap) can be characterized as
\[
\lambda_{\mathrm{gap}} = \min\{\lambda_{\mathrm{gap}}^{\mathcal X},\,\lambda_{\mathrm{gap}}^{\mathcal Y}\},
\]
where
\[
\lambda_{\mathrm{gap}}^{\mathcal X}
=
\inf_{\substack{\phi \in W^{2,2}(\mathcal X)\\ \nabla\phi \neq 0}}
\frac{\int \bigl(|\nabla^2\phi|^2 + \langle \nabla\phi,\nabla^2 V_{\nu^*}\nabla\phi\rangle\bigr)\,d\mu^*}
{\int |\nabla\phi|^2\,d\mu^*},
\qquad
V_{\nu^*}(x)=\int f(x,y)\,d\nu^*(y),
\]
and
\[
\lambda_{\mathrm{gap}}^{\mathcal Y}
=
\inf_{\substack{\phi \in W^{2,2}(\mathcal Y)\\ \nabla\phi \neq 0}}
\frac{\int \bigl(|\nabla^2\phi|^2 + \langle \nabla\phi,\nabla^2 U_{\mu^*}\nabla\phi\rangle\bigr)\,d\nu^*}
{\int |\nabla\phi|^2\,d\nu^*},
\qquad
U_{\mu^*}(y)=\int f(x,y)\,d\mu^*(x).
\]

\end{remark}

