\begin{theorem}[Well-posedness and instantaneous smoothing]\label{thm:main_appendix}
Let $M:=\mathbb T^n$ and let $\mu_0,\nu_0\in\mathcal P(M)$ be arbitrary probability measures.
Assume $f\in C^2(M\times M)$.
Then for every $T>0$ the coupled system \eqref{eq-main}
admits a unique narrowly continuous distributional solution $(\mu_t,\nu_t)_{t\in[0,T]}$
in the sense of \eqref{eq:weak_mu2}--\eqref{eq:weak_nu2}.
Moreover, for every $\tau\in(0,T)$ there exist densities $u,v$ on $(\tau,T]\times M$ such that
$\mu_t=u(t,\cdot)\,dx$ and $\nu_t=v(t,\cdot)\,dx$ for all $t\in(\tau,T]$, and for every $p\in(1,\infty)$,
\begin{equation}\label{eq:max_reg_statement}
u,v\in L^p((\tau,T);W^{2,p}(M))\cap W^{1,p}((\tau,T);L^p(M)).
\end{equation}
\end{theorem}
